    public static int sumOfEvenNumbers(int n) {
        if (n <= 0) {
            return 0;
        }

        // Number of even terms from 1 to n
        int count = n / 2;

        // Sum of first k even numbers: 2 + 4 + ... + 2k = 2 * (1 + 2 + ... + k)
        // = 2 * (k * (k + 1) / 2) = k * (k + 1)
        return count * (count + 1);
    }

